// Body: { run_id, products: [...] }  or  { run_id, source_url, offset, limit }
// Each product: { product_id, name, product_class, description }
const body = $input.first().json.body || {};
let products = Array.isArray(body.products) ? body.products : [];
if (!products.length && body.source_url) {
  const all = await this.helpers.httpRequest({ url: String(body.source_url), json: true });
  const offset = Number(body.offset) || 0;
  const limit = Number(body.limit) || 50;
  products = (Array.isArray(all) ? all : []).slice(offset, offset + limit);
}
const runId = String(body.run_id || ('run_' + $now.toFormat('yyyyLLdd_HHmmss')));
const SIZE = 10;  // products per Claude call
const out = [];
for (let i = 0; i < products.length; i += SIZE) {
  const batch = products.slice(i, i + SIZE).map(p => ({
    product_id: Number(p.product_id),
    name: String(p.name || ''),
    product_class: String(p.product_class || ''),
    // Long descriptions are cut to keep each call small
    description: String(p.description || '').slice(0, 1200),
  }));
  const text = batch.map(p => `### Product ${p.product_id}\nName: ${p.name}\nCategory: ${p.product_class}\nDescription: ${p.description}`).join('\n\n');
  out.push({ json: { run_id: runId, batch, text } });
}
return out;

// Turns Claude's lines into one row per product and attribute.
// Each line: product|style|evidence|color|evidence|shape|evidence|material|evidence
// A value is only proposed if it is an allowed value AND its evidence is found in the product text.
const ALLOWED = {"style": ["modern", "traditional", "glam", "farmhouse", "industrial", "coastal", "boho", "lodge"], "color": ["white", "black", "gray", "brown", "blue", "beige", "green", "red", "pink", "yellow", "orange", "purple", "silver", "gold", "clear", "multicolor"], "shape": ["rectangular", "square", "round", "oval", "l-shaped", "u-shaped", "hexagonal", "octagonal"], "material": ["metal", "wood", "plastic", "glass", "ceramic", "fabric", "natural fiber", "stone"]};
const ATTRS = Object.keys(ALLOWED);
const flat = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const batches = $('Split into batches of 10').all();
const rows = [];
$input.all().forEach((item, i) => {
  const b = batches[i].json;
  const failed = !!item.json.error || typeof item.json.text !== 'string';
  const byId = {};
  if (!failed) {
    item.json.text.split('\n').forEach(line => {
      const f = line.split('|').map(s => s.trim());
      if (f.length < 9 || !/^\d+$/.test(f[0])) return;
      const a = {};
      ATTRS.forEach((attr, k) => { a[attr] = { value: f[1 + 2 * k], evidence: f[2 + 2 * k] }; });
      byId[Number(f[0])] = a;
    });
  }
  b.batch.forEach(p => {
    const hay = flat(p.name + ' ' + p.product_class + ' ' + p.description);
    ATTRS.forEach(attr => {
      const a = byId[p.product_id] && byId[p.product_id][attr];
      const value = a ? String(a.value || '').toLowerCase().trim() : '';
      const evidence = a ? String(a.evidence || '').trim().slice(0, 200) : '';
      let status;
      if (failed) status = 'ai_failed';
      else if (!a) status = 'missing_in_answer';
      else if (!value || value === 'not_stated') status = 'not_stated';
      else if (!ALLOWED[attr].includes(value)) status = 'rejected_invalid_value';
      else if (flat(evidence).length < 3 || !hay.includes(flat(evidence))) status = 'rejected_no_evidence';
      else status = 'proposed';
      rows.push({ json: { run_id: b.run_id, product_id: p.product_id, product_name: p.name.slice(0, 200), attribute: attr,
        value: ['proposed', 'rejected_no_evidence', 'rejected_invalid_value'].includes(status) ? value : '', evidence, status } });
    });
  });
});
return rows;

// Compact reply: counts by status, plus every answer that has a value.
// Rows with no value (not_stated, ai_failed) are counted but not listed. All rows are in the cae_proposals table.
const rows = $('Check answers').all().map(i => i.json);
const count = {};
rows.forEach(r => { count[r.status] = (count[r.status] || 0) + 1; });
const failed = [...new Set(rows.filter(r => r.status === 'ai_failed').map(r => r.product_id))];
const results = rows.filter(r => r.value).map(r => [r.product_id, r.attribute, r.value, r.status === 'proposed' ? 'p' : r.status, r.evidence]);
return [{ json: { run_id: rows[0] ? rows[0].run_id : null, products: new Set(rows.map(r => r.product_id)).size, by_status: count, failed_products: failed, results } }];
